import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { build } from './build';
import { ServeOptions } from './types';

// WebSocket script to inject
const RELOAD_SCRIPT = `
<script>
(function() {
  var socket = new WebSocket('ws://localhost:${PORT}/__livereload');
  socket.onmessage = function(msg) {
    if (msg.data === 'reload') {
      window.location.reload();
    }
  };
})();
</script>
`;

export function serve(options: ServeOptions): void {
  const { contentDir, outputDir, templatesDir, port } = options;

  // Do initial build
  build({ contentDir, outputDir, templatesDir });

  const server = http.createServer((req, res) => {
    // Handle requests
    const url = req.url || '/';
    const filePath = url === '/' 
      ? path.join(outputDir, 'index.html')
      : path.join(outputDir, url);

    // Check if path is within outputDir for security
    const resolved = path.resolve(filePath);
    if (!resolved.startsWith(path.resolve(outputDir))) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) {
      res.writeHead(404);
      res.end('Not Found');
      return;
    }

    const ext = path.extname(resolved).toLowerCase();
    const mimeTypes: Record<string, string> = {
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.svg': 'image/svg+xml',
    };

    let content = fs.readFileSync(resolved, 'utf-8');
    if (ext === '.html') {
      content = content.replace('</body>', RELOAD_SCRIPT + '</body>');
    }

    res.writeHead(200, { 'Content-Type': mimeTypes[ext] || 'application/octet-stream' });
    res.end(content);
  });

  const wss = new WebSocketServer({ server });

  // File watcher
  const watchPaths = [
    contentDir,
    templatesDir || './templates',
  ];

  let rebuildTimeout: NodeJS.Timeout | null = null;
  let sockets: WebSocket[] = [];

  wss.on('connection', (ws) => {
    sockets.push(ws);
    ws.on('close', () => {
      sockets = sockets.filter(s => s !== ws);
    });
  });

  const watcher = chokidar.watch(watchPaths, { ignoreInitial: true });

  watcher.on('all', (event, filePath) => {
    console.log(`[change] ${event}: ${filePath}`);
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(() => {
      try {
        build({ contentDir, outputDir, templatesDir });
        console.log('[rebuilt]');
        // Notify all connected clients
        sockets.forEach(ws => {
          if (ws.readyState === WebSocket.OPEN) {
            ws.send('reload');
          }
        });
      } catch (err) {
        console.error('[build error]', (err as Error).message);
      }
    }, 100);
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}/`);
  });
}
