import http from 'http';
import fs from 'fs';
import path from 'path';
import { serve } from '../src/serve';

function createTempDir(prefix: string): string {
  const dir = path.resolve(__dirname, '..', `${prefix}-${Date.now()}`);
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function cleanupDir(dir: string): void {
  if (fs.existsSync(dir)) fs.rmSync(dir, { recursive: true, force: true });
}

function get(url: string, port: number, host: string = 'localhost'): Promise<{ status: number; body: string; headers: http.IncomingHttpHeaders }> {
  return new Promise((resolve, reject) => {
    http.get(`http://${host}:${port}${url}`, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
